# ── Live state broadcast ─────────────────────────────────────────────────────

class StateHub:
    """Fans JARVIS's current state out to every connected browser.

    The visualiser reads this to decide how to animate: calm when idle,
    agitated while thinking, pulsing while speaking.
    """

    VALID = {"idle", "listening", "thinking", "speaking", "error"}

    # Transient states the browser is expected to clear when it finishes. If it
    # never does, these are the ones that wedge.
    TRANSIENT = {"speaking", "listening", "thinking"}

    # Longest a reply could plausibly take to speak aloud. Deliberately not
    # derived from `detail`, which is truncated to 80 characters and so says
    # nothing about the length of the actual utterance.
    SPEAKING_CEILING_SEC = 180.0

    def __init__(self) -> None:
        self._clients: set[WebSocket] = set()
        self.state = "idle"
        self.detail = ""
        self._watchdog: asyncio.Task | None = None

    async def connect(self, ws: WebSocket) -> None:
        await ws.accept()
        self._clients.add(ws)
        await self._send(ws, {"type": "state", "state": self.state,
                              "detail": self.detail})

    async def disconnect(self, ws: WebSocket) -> None:
        self._clients.discard(ws)
        # A state describing what the UI is doing is meaningless once there is
        # no UI. Without this, a browser killed mid-sentence leaves the server
        # permanently convinced JARVIS is still talking.
        if not self._clients and self.state in self.TRANSIENT:
            logger.info(f"last client gone while {self.state!r} — resetting to idle")
            await self.set("idle", "")

    async def set(self, state: str, detail: str = "") -> None:
        if state not in self.VALID:
            state = "idle"
        self.state = state
        self.detail = detail
        self._arm_watchdog(state)
        await self.broadcast({"type": "state", "state": state, "detail": detail})

    def _arm_watchdog(self, state: str) -> None:
        """Bound how long 'speaking' can last without the client clearing it.

        `speaking` is set here but only ever cleared by the browser reporting
        back over the websocket. That is fine until the browser dies mid-reply,
        loses its socket, or is force-quit — then nothing clears it and the
        star pulses forever while anything gating on "is JARVIS talking?"
        believes it still is. Observed exactly that: a client killed mid-speech
        left the server stuck in `speaking` indefinitely.
        """
        if self._watchdog and not self._watchdog.done():
            self._watchdog.cancel()
        self._watchdog = None
        if state != "speaking":
            return
        self._watchdog = asyncio.create_task(self._expire_speaking())

    async def _expire_speaking(self) -> None:
        try:
            await asyncio.sleep(self.SPEAKING_CEILING_SEC)
        except asyncio.CancelledError:
            return
        if self.state == "speaking":
            logger.warning(
                f"still 'speaking' after {self.SPEAKING_CEILING_SEC:.0f}s — "
                "client never reported finishing; resetting to idle")
            await self.set("idle", "")

    async def broadcast(self, payload: dict[str, Any]) -> None:
        # Copy first: a failing send mutates the set mid-iteration.
        for ws in list(self._clients):
            await self._send(ws, payload)

    async def _send(self, ws: WebSocket, payload: dict[str, Any]) -> None:
        try:
            await ws.send_text(json.dumps(payload))
        except Exception:
            self._clients.discard(ws)

    @property
    def client_count(self) -> int:
        return len(self._clients)


hub = StateHub()


