# How often to look for new WhatsApp notifications.
#
# 2s, not the original 20s: a notification you hear about twenty seconds later
# is not a notification, it is a summary. The cost is one local sqlite query —
# measured at 2-6ms against this database — so a 2s loop runs at well under 1%
# duty cycle and never leaves the machine.
WHATSAPP_POLL_SEC = 2.0


# Watcher state, surfaced in /api/status. Whether the watcher is alive was
# only discoverable by grepping a log file that stops existing the moment
# Neutron (rather than a shell) owns the process — which is precisely when it
# silently turned itself off for lack of Full Disk Access.
WATCHER = {"watching": False, "reason": "not started", "seen": 0,
           "last": ""}


async def _whatsapp_watcher() -> None:
    """Announce WhatsApp messages as they arrive.

    Seeded from the newest existing notification, so starting JARVIS does not
    read out a backlog of everything already on screen — only what arrives
    from now on.

    Silently does nothing when Full Disk Access is missing. That is the right
    behaviour for an optional feature, and `preflight.py` is where the user is
    told about the permission, so the silence here is not a hidden failure.
    """
    from integrations.whatsapp import notification_reader as nr

    ok, why = await asyncio.to_thread(nr.available)
    if not ok:
        WATCHER.update(watching=False, reason=why)
        logger.info(f"WhatsApp watcher off: {why}")
        return

    last = await asyncio.to_thread(nr.latest_timestamp)
    WATCHER.update(watching=True, reason="")
    logger.info("WhatsApp watcher started")
    while True:
        try:
            await asyncio.sleep(WHATSAPP_POLL_SEC)
            notes = await asyncio.to_thread(nr.recent, last, 20)
            if not notes:
                continue
            last = notes[-1].when
            text = await asyncio.to_thread(nr.summarise, notes)
            WATCHER["seen"] += len(notes)
            WATCHER["last"] = text[:120]
            logger.info(f"WhatsApp: {len(notes)} new — {text[:60]!r}")
            # A dedicated type, not "reply": the front end only speaks replies
            # to its own requests, and this was nobody's request.
            await hub.broadcast({"type": "whatsapp", "text": text,
                                 "count": len(notes)})
        except asyncio.CancelledError:
            raise
        except Exception as exc:  # noqa: BLE001 — a watcher must not die
            logger.debug(f"WhatsApp watcher error: {exc}")


@asynccontextmanager
async def lifespan(app: FastAPI):
    print("  warming registry + memory store…")
    registry(), memory()
    print(f"  ✓ {len(registry().all_skills())} skills ready")
    watcher = asyncio.create_task(_whatsapp_watcher())
    yield
    watcher.cancel()


app = FastAPI(title="JARVIS Web", version="1.0", lifespan=lifespan)

# Local-only tool, but the Electron app and `file://` pages both count as
# foreign origins, so allow them rather than debug CORS later.
app.add_middleware(
    CORSMiddleware, allow_origins=["*"], allow_methods=["*"],
    allow_headers=["*"],
)


@app.middleware("http")
async def _no_cache_static(request, call_next):
    """Never let the front end run a stale build.

    Electron caches /static/app.js like any Chromium browser, so relaunching
    the app was not enough to pick up JS changes — it silently kept the old
    file. That cost real debugging time: the WhatsApp push handler was added,
    the server broadcast correctly, and nothing happened, because the running
    front end had never seen the handler.

    This is a local single-user tool; caching buys nothing and hides changes.
    """
    response = await call_next(request)
    if request.url.path.startswith("/static") or request.url.path in ("/", "/brain"):
        response.headers["Cache-Control"] = "no-store, must-revalidate"
    return response


# BCP-47 tag → the name to put in the prompt. Asking for "reply in ta-IN"
# gets noticeably worse output than asking for "reply in Tamil".
LANG_NAMES = {
    "en": "English", "ta": "Tamil", "hi": "Hindi", "kn": "Kannada",
    "ml": "Malayalam", "ja": "Japanese", "zh": "Chinese", "es": "Spanish",
    "ar": "Arabic", "fr": "French", "pt": "Portuguese", "ru": "Russian",
    "de": "German", "ko": "Korean", "it": "Italian", "id": "Indonesian",
    "tr": "Turkish", "vi": "Vietnamese", "th": "Thai", "nl": "Dutch",
    "pl": "Polish", "te": "Telugu", "bn": "Bengali", "mr": "Marathi",
    "gu": "Gujarati", "pa": "Punjabi", "ur": "Urdu",
}


def language_name(tag: str) -> str:
    return LANG_NAMES.get((tag or "en").split("-")[0].lower(), "English")


