# ── Command execution ────────────────────────────────────────────────────────

@app.post("/api/command")
async def command(body: CommandIn) -> dict[str, Any]:
    """Route text through the skill registry, exactly like the voice loop."""
    text = body.text.strip()
    if not text:
        raise HTTPException(400, "empty command")

    started = time.perf_counter()
    await hub.set("thinking", text[:80])

    skill, match = registry().match(text)
    used_llm = False
    # `source` is the ROUTING TIER, not the channel. It has to match the values
    # core/command_router.py writes ('regex' | 'local' | 'llm'), because
    # training/collect_feedback.py selects on source='regex' to build its
    # labels. Writing 'web' here silently excluded every web conversation from
    # JARVIS's learning loop.
    source = "regex"

    # The 0.85 gate means "if unsure, let the LLM answer instead". That is
    # right for ambiguous phrasing, but it silently disabled every skill that
    # deliberately bids low to avoid out-ranking a specific one — research bids
    # 0.62 so "what time is it" still reaches time_date, and was therefore
    # never reached at all. Medium-confidence matches now run their skill.
    MEDIUM = 0.60
    conf = match.confidence if match else 0.0

    try:
        if skill is not None and (registry().is_high_confidence(match)
                                  or conf >= MEDIUM):
            # Carry the language through to skills that support it.
            entities = dict(match.entities or {})
            entities.setdefault("lang_code", body.lang)
            result = await skill.run(text, entities)
            reply = result.text
            skill_name = skill.name
            confidence = match.confidence
            if not registry().is_high_confidence(match):
                source = "local"    # routed by score, not an exact pattern
        else:
            # Low confidence — hand it to the conversation engine, which has
            # its own provider fallback chain underneath.
            used_llm = True
            source = "llm"
            # Steer the reply language. The recogniser already transcribed in
            # this locale, so the user is speaking it — answering in English
            # would be a non-sequitur.
            name = language_name(body.lang)

            # Retrieval: pull anything JARVIS has read that bears on the
            # question and hand it over as context. This is what lets it
            # answer from Ruthish's own notes rather than from generic
            # training data — and it updates the moment a file is indexed.
            context = ""
            try:
                # Connect, query and close inside ONE worker thread. sqlite3
                # defaults to check_same_thread=True, so opening the handle in
                # one thread and querying from another raises — and because
                # this is wrapped in a catch-all, the failure was invisible and
                # JARVIS just quietly answered as if it had read nothing.
                def _lookup(q: str) -> str:
                    from brain.knowledge import connect, search, build_context
                    conn = connect()
                    try:
                        hits = search(conn, q, 5)
                        return build_context(hits) if hits else ""
                    finally:
                        conn.close()

                context = await asyncio.to_thread(_lookup, text)
            except Exception as exc:  # noqa: BLE001 — never block a reply
                # Warning, not debug: a silent retrieval failure looks exactly
                # like "nothing was indexed", which is a lie.
                logging.getLogger(__name__).warning("knowledge lookup failed: %s", exc)

            # The retrieved context is NOT put in `parts`. Whatever goes into
            # the prompt is written to conversation memory and replayed on
            # every future turn, so documents accumulated until the request
            # exceeded Groq's token-per-minute limit. It is passed separately
            # below as ephemeral, this-turn-only material instead.
            parts = [text]
            # The language instruction is NOT appended to the prompt. Whatever
            # goes in the prompt is written to conversation memory and replayed
            # every turn, so a ~350-character instruction would accumulate the
            # same way the retrieved documents did. It is passed as `lang_code`
            # instead and placed in the system message by the engine.
            prompt = "".join(parts)
            # Retrieval context goes as an EPHEMERAL argument, not inside the
            # prompt. Prepending it meant every turn stored ~3,500 characters
            # of documents in conversation memory forever, and twenty turns
            # later every request exceeded Groq's 8,000 TPM limit.
            reply = await asyncio.to_thread(
                engine().chat, prompt, context or None, body.lang)
            skill_name = "conversation"
            confidence = match.confidence if match else 0.0
    except Exception as exc:
        await hub.set("error", str(exc)[:80])
        return JSONResponse(
            {"ok": False, "error": f"{type(exc).__name__}: {exc}",
             "reply": "Something went wrong running that."},
            status_code=500,
        )

    elapsed = (time.perf_counter() - started) * 1000

    try:
        memory().log_event(text, reply, skill_name,
                           source=source, confidence=confidence)
    except Exception:
        pass  # never let logging break a reply

    # Not "speaking" — the server never speaks. Audio happens in the browser,
    # which owns that transition and reports it back over the websocket when
    # the utterance actually ends.
    #
    # Claiming it here was wrong in both directions. An HTTP caller (curl, a
    # script, the Brain window) does not speak at all, and the front end only
    # speaks replies from its own fetch — it ignores `reply` broadcasts — so
    # nothing was ever going to clear the flag. The server sat in "speaking"
    # indefinitely: the star pulsed for a reply that finished minutes earlier,
    # and anything asking "is JARVIS talking?" got a permanent yes.
    await hub.set("idle", reply[:80])
    await hub.broadcast({"type": "reply", "text": reply, "skill": skill_name})

    return {
        "ok": True,
        "reply": reply,
        "skill": skill_name,
        "confidence": round(confidence, 3),
        "used_llm": used_llm,
        "latency_ms": round(elapsed),
    }


