def _prefix_search_facts(q: str, limit: int) -> list[dict[str, Any]]:
    """Prefix ('starts with') search over the facts FTS index. Read-only."""
    import sqlite3

    safe = "".join(c if (c.isalnum() or c.isspace()) else " " for c in q)
    tokens = [t for t in safe.split() if t]
    if not tokens:
        return []
    expr = " OR ".join(f'"{t}"*' for t in tokens)

    try:
        conn = sqlite3.connect(f"file:{DB_PATH}?mode=ro", uri=True)
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            "SELECT f.id, f.text, f.tags FROM facts_fts fts "
            "JOIN facts f ON f.id = fts.rowid "
            "WHERE facts_fts MATCH ? ORDER BY rank LIMIT ?",
            (expr, limit),
        ).fetchall()
        conn.close()
        return [{"id": r["id"], "text": r["text"], "tags": r["tags"]}
                for r in rows]
    except Exception:
        return []


@app.get("/api/search")
def search(q: str, limit: int = 10) -> dict[str, Any]:
    q = (q or "").strip()
    if not q:
        return {"facts": [], "events": []}
    limit = max(1, min(limit, 50))
    store = memory()
    try:
        found_facts = [{"id": f.id, "text": f.text, "tags": f.tags}
                       for f in store.recall(q, limit=limit)]
        # FTS5 matches whole tokens, so "graduate" misses "graduates", and
        # `MemoryStore._fts_query` strips `*` while sanitising. Run the prefix
        # form directly against the index rather than report a false empty.
        if not found_facts:
            found_facts = _prefix_search_facts(q, limit)
    except Exception:
        found_facts = []
    try:
        found_events = [{"user": u, "reply": r}
                        for u, r in store.search_events(q, limit=limit)]
    except Exception:
        found_events = []
    return {"facts": found_facts, "events": found_events}


