class LearnIn(BaseModel):
    url: str | None = None
    path: str | None = None
    topic: str | None = None
    depth: int = 4


@app.get("/api/knowledge")
def knowledge_stats() -> dict[str, Any]:
    try:
        from brain.knowledge import connect, stats
        conn = connect()
        out = stats(conn)
        conn.close()
        return {"ok": True, **out}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": f"{type(exc).__name__}: {exc}"}


@app.get("/api/knowledge/search")
def knowledge_search(q: str, limit: int = 6) -> dict[str, Any]:
    try:
        from brain.knowledge import connect, search
        conn = connect()
        hits = search(conn, q, max(1, min(limit, 20)))
        conn.close()
        return {"ok": True, "hits": hits}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": str(exc), "hits": []}


@app.post("/api/knowledge/learn")
async def knowledge_learn(body: LearnIn) -> dict[str, Any]:
    """Read a URL, a file or folder, or go explore a topic on the web."""
    try:
        from brain.knowledge import (connect, add_source, add_file, add_dir,
                                     explore, fetch_url)
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": str(exc)}

    def work() -> list[dict]:
        conn = connect()
        try:
            if body.topic:
                return explore(conn, body.topic, max(1, min(body.depth, 8)))
            if body.url:
                title, text = fetch_url(body.url)
                return [add_source(conn, body.url, title or body.url, text, "web")]
            if body.path:
                p = Path(body.path).expanduser()
                if p.is_dir():
                    return add_dir(conn, p)
                return [add_file(conn, p)]
            return []
        finally:
            conn.close()

    try:
        results = await asyncio.to_thread(work)
        return {"ok": True, "results": results,
                "chunks": sum(r.get("chunks", 0) for r in results)}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": f"{type(exc).__name__}: {exc}"}


# ── Speech to text ───────────────────────────────────────────────────────────

@app.post("/api/transcribe")
async def transcribe_audio(
    audio: UploadFile = File(...),
    lang: str = Form("en-US"),
) -> dict[str, Any]:
    """Transcribe a recorded clip.

    The desktop apps use this instead of the browser speech API, which cannot
    work in Electron — see web/transcribe.py for why.
    """
    data = await audio.read()
    # Whisper is CPU-bound and the model call blocks; keep it off the event
    # loop or every connected window freezes while someone speaks.
    from web.transcribe import transcribe as run_stt
    result = await asyncio.to_thread(
        run_stt, data, audio.filename or "audio.webm", lang)
    return result


# ── Brain: learning status + manual cycle ────────────────────────────────────

@app.get("/api/brain")
def brain_status() -> dict[str, Any]:
    """What JARVIS has learned, and how much is waiting to be learned."""
    try:
        from brain.autonomous import status as brain_state
        return {"ok": True, **brain_state()}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": f"{type(exc).__name__}: {exc}"}


@app.post("/api/brain/learn")
async def brain_learn(force: bool = False) -> dict[str, Any]:
    """Kick a learning cycle by hand.

    Runs in a worker thread: a retrain takes minutes and would otherwise
    block the event loop, freezing every connected browser.
    """
    try:
        from brain.autonomous import cycle
        await hub.broadcast({"type": "learning", "phase": "start"})
        entry = await asyncio.to_thread(cycle, force, 100, True)
        await hub.broadcast({"type": "learning", "phase": "done",
                             "outcome": entry.get("outcome")})
        return {"ok": True, "result": entry}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": f"{type(exc).__name__}: {exc}"}


# ── Neural voice ─────────────────────────────────────────────────────────────

# The browser speaks replies with `speechSynthesis`, which on macOS is the flat
# system voice. ElevenLabs was configured and working, but only on the Python
# path used by `run.py` — the desktop apps never touched it, so the voice
# Ruthish set up was the one voice he never heard.
#
# This serves the same ElevenLabs audio to the browser. MP3 rather than the
# PCM the Python engine uses: an <audio> element decodes MP3 natively, where
# raw PCM would need manual Web Audio framing for no benefit.
#
# Cached on disk by (voice, model, text). JARVIS repeats itself constantly —
# greetings, acknowledgements, "opening Chrome" — and a cache hit is local
# disk instead of a network round trip.

TTS_CACHE = ROOT / "data" / "tts_web_cache"
TTS_FORMAT = "mp3_22050_32"


class TTSRequest(BaseModel):
    text: str
    lang: str = "en-US"


@app.post("/api/tts")
async def tts(req: TTSRequest):
    """ElevenLabs audio for the browser. 503 means 'use speechSynthesis'."""
    from config import settings

    text = (req.text or "").strip()
    if not text:
        raise HTTPException(400, "empty text")

    key = settings.ELEVENLABS_API_KEY
    voice = settings.ELEVENLABS_VOICE_ID
    model = getattr(settings, "ELEVENLABS_MODEL", "eleven_flash_v2_5")
    if not key or not voice:
        # Not an error: the front end falls back to the browser voice.
        raise HTTPException(503, "ElevenLabs not configured")

    TTS_CACHE.mkdir(parents=True, exist_ok=True)
    import hashlib

    digest = hashlib.sha256(f"{voice}|{model}|{text}".encode()).hexdigest()[:20]
    path = TTS_CACHE / f"{digest}.mp3"

    if path.exists():
        return FileResponse(path, media_type="audio/mpeg",
                            headers={"X-Cache": "hit"})

    def _fetch() -> bytes:
        import requests

        r = requests.post(
            f"https://api.elevenlabs.io/v1/text-to-speech/{voice}",
            params={"output_format": TTS_FORMAT, "optimize_streaming_latency": 3},
            headers={"xi-api-key": key, "Content-Type": "application/json"},
            json={"text": text, "model_id": model},
            timeout=(6, 30),
        )
        r.raise_for_status()
        return r.content

    try:
        audio = await asyncio.to_thread(_fetch)
    except Exception as exc:
        # Never hard-fail: a 503 tells the browser to use its own voice, which
        # is worse-sounding but still speech. Silence would be worse than both.
        logger.warning(f"ElevenLabs TTS failed: {exc}")
        raise HTTPException(503, "tts unavailable")

    try:
        path.write_bytes(audio)
    except Exception:
        pass  # caching is an optimisation, never a reason to fail the request

    from fastapi.responses import Response

    return Response(content=audio, media_type="audio/mpeg",
                    headers={"X-Cache": "miss"})


# ── WebSocket ────────────────────────────────────────────────────────────────

@app.websocket("/ws")
async def ws_endpoint(ws: WebSocket) -> None:
    await hub.connect(ws)
    try:
        while True:
            raw = await ws.receive_text()
            try:
                msg = json.loads(raw)
            except json.JSONDecodeError:
                continue
            # The browser reports mic state so the visualiser can react
            # before the command round trip even starts.
            if msg.get("type") == "state":
                await hub.set(msg.get("state", "idle"), msg.get("detail", ""))
            elif msg.get("type") == "ping":
                await ws.send_text(json.dumps({"type": "pong"}))
    except WebSocketDisconnect:
        await hub.disconnect(ws)
    except Exception:
        await hub.disconnect(ws)


# ── Static front end ─────────────────────────────────────────────────────────

@app.get("/")
def index() -> FileResponse:
    """The JARVIS app — star, voice-first."""
    return FileResponse(STATIC / "index.html")


@app.get("/brain")
def brain_page() -> FileResponse:
    """The Brain app — cortical visual plus every control."""
    return FileResponse(STATIC / "brain.html")


if STATIC.is_dir():
    app.mount("/static", StaticFiles(directory=STATIC), name="static")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--port", type=int, default=8420)
    ap.add_argument("--reload", action="store_true")
    args = ap.parse_args()

    print("\n" + "=" * 62)
    print("  JARVIS Web")
    print(f"  → http://{args.host}:{args.port}")
    print("=" * 62 + "\n")

    import uvicorn
    uvicorn.run("web.server:app" if args.reload else app,
                host=args.host, port=args.port,
                reload=args.reload, log_level="warning")
    return 0


if __name__ == "__main__":
    sys.exit(main())
